    /**
     * Create MilStdSymbol from tactical graphic
     *
     * @deprecated
     * @param tg tactical graphic
     * @param converter geographic to pixels to converter
     * @return MilstdSymbol object
     */
    static createMilStdSymboFromTGLight(tg, converter) {
        let milStd;
        try {
            let symbolId = tg.get_SymbolId();
            let lineType = clsUtility_1.clsUtility.GetLinetypeFromString(symbolId);
            let status = tg.get_Status();
            //build tg.Pixels
            tg.Pixels = clsUtility_2.clsUtility.LatLongToPixels(tg.LatLongs, converter);
            let isClosedArea = clsUtility_1.clsUtility.isClosedPolygon(lineType);
            if (isClosedArea) {
                clsUtility_1.clsUtility.ClosePolygon(tg.Pixels);
                clsUtility_1.clsUtility.ClosePolygon(tg.LatLongs);
            }
            let coords = clsRenderer.getClientCoords(tg);
            tg.set_Font(new Font_1.Font("Arial", Font_1.Font.PLAIN, 12));
            let modifiers = new Map();
            modifiers.set(Modifiers_1.Modifiers.W_DTG_1, tg.get_DTG());
            modifiers.set(Modifiers_1.Modifiers.W1_DTG_2, tg.get_DTG1());
            modifiers.set(Modifiers_1.Modifiers.H_ADDITIONAL_INFO_1, tg.get_H());
            modifiers.set(Modifiers_1.Modifiers.H1_ADDITIONAL_INFO_2, tg.get_H1());
            modifiers.set(Modifiers_1.Modifiers.H2_ADDITIONAL_INFO_3, tg.get_H2());
            modifiers.set(Modifiers_1.Modifiers.T_UNIQUE_DESIGNATION_1, tg.get_Name());
            modifiers.set(Modifiers_1.Modifiers.T1_UNIQUE_DESIGNATION_2, tg.get_T1());
            modifiers.set(Modifiers_1.Modifiers.Y_LOCATION, tg.get_Location());
            modifiers.set(Modifiers_1.Modifiers.N_HOSTILE, tg.get_N());
            milStd = new MilStdSymbol_1.MilStdSymbol(symbolId, "1", coords, modifiers);
            milStd.setFillColor(tg.get_FillColor());
            milStd.setLineColor(tg.get_LineColor());
            milStd.setLineWidth(tg.get_LineThickness());
            milStd.setFillStyle(tg.get_TexturePaint());
            milStd.setPatternScale(tg.get_patternScale());
        }
        catch (exc) {
            if (exc instanceof Error) {
                ErrorLogger_1.ErrorLogger.LogException("clsRenderer", "createMilStdSymboFromTGLight", new RendererException_1.RendererException("Failed to set geo points or pixels for " + tg.get_SymbolId(), exc));
            }
            else {
                throw exc;
            }
        }
        return milStd;
    }
