    static AddOffsetModifier(tg, text, type, lineFactor, startIndex, endIndex, spaces, rightOrLeft) {
        if (rightOrLeft == null || tg.Pixels == null || tg.Pixels.length < 2 || endIndex >= tg.Pixels.length) {
            return;
        }
        let pt0 = tg.Pixels[startIndex];
        let pt1 = tg.Pixels[endIndex];
        if (rightOrLeft === "left") {
            pt0.x -= spaces;
            pt1.x -= spaces;
        }
        else {
            pt0.x += spaces;
            pt1.x += spaces;
        }
        Modifier2.AddModifier2(tg, text, type, lineFactor, pt0, pt1, false);
    }
