            //for (j = 1; j < geoPoints.length; j++) 
            for (j = 1; j < n; j++) {
                pt = geoPoints[j];
                if (pt.x < minx) {
                    minx = pt.x;
                }
                if (pt.x > maxx) {
                    maxx = pt.x;
                }
            }
            if (maxx - minx > 180) {
                spansIDL = true;
            }
            if (!spansIDL) {
                return geoPoints;
            }
            normalizedPts = new Array();
            n = geoPoints.length;
            //for (j = 0; j < geoPoints.length; j++) 
            for (j = 0; j < n; j++) {
                pt = geoPoints[j];
                if (pt.x < 0) {
                    pt.x += 360;
                }
                normalizedPts.push(pt);
            }
